  secedit /export /cfg $f /areas SECURITYPOLICY USER_RIGHTS /quiet | Out-Null
  $c = Get-Content $f -ErrorAction SilentlyContinue
  Remove-Item $f -Force -ErrorAction SilentlyContinue
  $line = $c | Where-Object { $_ -match ('^\s*' + $Key + '\s*=') } | Select-Object -First 1
  if ($line) { ($line -split '=', 2)[1].Trim().Trim('"') } else { $null }
}
function Backup-TmaSec {
  $bk = Join-Path $env:ProgramData 'TMAegis\backup'
  New-Item -ItemType Directory -Force -Path $bk | Out-Null
  secedit /export /cfg (Join-Path $bk ('secedit-' + (Get-Date -Format 'yyyyMMddHHmmss') + '.inf')) /areas SECURITYPOLICY USER_RIGHTS /quiet | Out-Null
}
function Set-TmaSec([string]$Section, [string]$Line) {
  $inf = Join-Path $env:TEMP ('tmaegis-' + [guid]::NewGuid().ToString() + '.inf')
  $db = Join-Path $env:TEMP ('tmaegis-' + [guid]::NewGuid().ToString() + '.sdb')
  $txt = @('[Unicode]', 'Unicode=yes', '[Version]', 'signature="$CHICAGO$"', 'Revision=1', ('[' + $Section + ']'), $Line) -join "`r`n"
  Set-Content -Path $inf -Value $txt -Encoding Unicode
  secedit /configure /db $db /cfg $inf /areas SECURITYPOLICY USER_RIGHTS /quiet | Out-Null
  $rc = $LASTEXITCODE
  Remove-Item $inf, $db -Force -ErrorAction SilentlyContinue
  if ($rc -ne 0) { throw ('secedit /configure failed: ' + $rc) }
}
function ToInt($x, $d) { if ($null -ne $x -and "$x" -match '^-?\d+$') { [int64]$x } else { $d } }
$thr = ToInt (Get-TmaSec 'LockoutBadCount') 0
$dur = ToInt (Get-TmaSec 'LockoutDuration') 0
$win = ToInt (Get-TmaSec 'ResetLockoutCount') 0
$nthr = $thr; if ($thr -le 0 -or $thr -gt 5) { $nthr = 5 }
$nwin = $win; if ($win -lt 15) { $nwin = 15 }
$ndur = $dur; if ($dur -lt 15) { $ndur = 15 }
if ($ndur -lt $nwin) { $ndur = $nwin }
if ($nthr -ne $thr -or $ndur -ne $dur -or $nwin -ne $win) {
  Backup-TmaSec
  net accounts /lockoutthreshold:$nthr /lockoutduration:$ndur /lockoutwindow:$nwin | Out-Null
  if ($LASTEXITCODE -ne 0) { throw 'net accounts failed' }
}

