$key = 'SeBatchLogonRight'
$cur = Get-TmaSec $key
$have = @(if ($cur) { $cur -split ',' | ForEach-Object { $_.Trim().TrimStart('*') } | Where-Object { $_ } })
if ((($have | Sort-Object -Unique) -join ',') -ne 'S-1-5-32-544') {
  Backup-TmaSec
  Set-TmaSec 'Privilege Rights' ($key + ' = ' + '*S-1-5-32-544')
}

